def make_question(index, row):
    tag, prompt, options, answer, reason = row
    option_objects = [{"id": chr(65 + i), "text": text} for i, text in enumerate(options)]
    answer_id = next(item["id"] for item in option_objects if item["text"] == answer)
    refs = [{"url": url, "title": f"{title}；僅研究公開題型與能力方向，未複製原題。", "year": "113-114", "subject": "social", "locator": locator, "observedPattern": "公立學校社會科公開試題常見的全球連結、資料推論與多尺度比較能力，經本題重新設計。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for url, title, locator in SOURCES]
    steps = [f"讀題定位：圈出「{tag}」的流向、節點、時間、尺度、群體與題目要求。", f"整理證據：把生產、運輸、貿易、勞動、環境與分配資料分開；核心理由是「{reason}」。", f"核對正解：選項 {answer_id}「{answer}」能同時處理全球連結的機會、風險或分配。", "排除誘答：檢查是否只看出口、交易額、最後組裝地或單一成功案例，找出被忽略的節點與群體。", "結論回查：確認證據範圍足以支持結論；若改變國家、產品或時間，必須重新判讀。"]
    return {"id": f"question-social-content-geo-bb-iv-3-{index}", "subject": "social", "type": "single-choice", "prompt": prompt, "options": option_objects, "knowledgeIds": ["kg-social-content-geo-bb-iv-3"], "difficulty": "medium", "answer": {"value": answer_id, "explanation": reason}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0][0], "sourceLocator": "高雄市立鹽埕國中三年級社會科公開段考；本題只研究公開試題能力結構與資料型態。", "authoringNote": "依官方課綱、單元 KG 與三個公立學校公開來源的題型方向，獨立改寫經濟全球關連情境；未複製原文、選項、圖表或答案；待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-09", "lessonId": "lesson-social-content-geo-bb-iv-3", "examPatternRefs": refs, "solutionStrategy": "先追蹤商品、資金或資訊流向，再確認節點與尺度，最後比較全球連結帶來的收益、風險與分配。", "solutionSteps": steps}

for index, row in enumerate(DATA, 1):
    (OUT / f"question-social-content-geo-bb-iv-3-{index}.json").write_text(json.dumps(make_question(index, row), ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
